  const applyLoadedOrder=(order:FoodOrderRecord|undefined,mode:ServiceMode,label:string,source:ReturnType<typeof loadLocalDatabase>)=>{setServiceMode(mode);setTableLabel((mode==="table"||mode==="delivery")?label:"");setQuery("");setCategory("Todos");setPayment("cash");setMixedCash("");setCashReceived("");setDiscountPercent(clampDiscount(Number(order?.discountPercent)||0));setInternalConsumption(Boolean(order?.internalConsumption));setLastSaleId("");setClearArmed(false);if(!order){setCart([]);setActiveOrderId("");resetCustomer();setDb(source);setMessage(mode==="table"?`Mesa ${label} · libre, lista para nuevo pedido`:mode==="delivery"?`Domicilio ${label} · listo para nuevo pedido`:`${serviceLabel[mode]} · listo para nuevo pedido`);return}const lines=linesFromOrder(order,source);setCart(lines);setActiveOrderId(order.id);setCustomerId(order.customerId||"");setCustomerName(order.customerName||"");setPhone(order.phone||"");setAddress(order.address||"");setOrderNotes(order.notes||"");setDb(source);setMessage(mode==="table"?`Mesa ${label} recuperada · ${lines.reduce((sum,line)=>sum+line.qty,0)} productos`:mode==="delivery"?`Domicilio ${label} recuperado · ${lines.reduce((sum,line)=>sum+line.qty,0)} productos`:`${serviceLabel[mode]} recuperado · ${lines.reduce((sum,line)=>sum+line.qty,0)} productos`)};
