  const persistCurrentContext=()=>{if(cart.length){const saved=saveOrder(true);return Boolean(saved)}if(activeOrderId)cancelActiveOrder();return true};

  const selectTable=(label:string)=>{if(activeServiceMode==="table"&&tableLabel===label)return;if(!persistCurrentContext())return;loadTableOrder(label,loadLocalDatabase())};
