    if(payment==="cash"&&!internalConsumption&&total>0&&cashReceived.trim()&&(!Number.isFinite(receivedNumber)||receivedNumber<total)){setMessage(`Recibido insuficiente · faltan ${money(total-(Number.isFinite(receivedNumber)?receivedNumber:0))}`);return}
